 "content": "def transform(grid):
    # Select the 9-cell object, as shown in the first two demonstrations.
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]!=0 and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            comps.append(comp)
    target=next((obj for obj in comps if len(obj)==9), min(comps,key=len))
    r0=min(r for r,c in target); r1=max(r for r,c in target)
    c0=min(c for r,c in target); c1=max(c for r,c in target)
    return [[int((r,c) in set(target)) for c in range(c0,c1+1)] for r in range(r0,r1+1)]
"
}

